    case disc(lat: Double, lon: Double, radiusM: Double
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
struct FfiConverterTypeShapeRegion: FfiConverterRustBuffer {
    typealias SwiftType = ShapeRegion

    static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ShapeRegion {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        case 1: return .disc(lat: try FfiConverterDouble.read(from: &buf), lon: try FfiConverterDouble.read(from: &buf), radiusM: try FfiConverterDouble.read(from: &buf)
        )
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    static func write(_ value: ShapeRegion, into buf: inout [UInt8]) {
        switch value {
        case let .disc(lat,lon,radiusM):
            writeInt(&buf, Int32(1))
            FfiConverterDouble.write(lat, into: &buf)
            FfiConverterDouble.write(lon, into: &buf)
            FfiConverterDouble.write(radiusM, into: &buf)
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
func FfiConverterTypeShapeRegion_lift(_ buf: RustBuffer) throws -> ShapeRegion {
    return try FfiConverterTypeShapeRegion.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
func FfiConverterTypeShapeRegion_lower(_ value: ShapeRegion) -> RustBuffer {
    return FfiConverterTypeShapeRegion.lower(value)
}



