enum SlimError {

    case Malformed(msg: String
    )
    case Unsupported(msg: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
struct FfiConverterTypeSlimError: FfiConverterRustBuffer {
    typealias SwiftType = SlimError

    static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SlimError {
        let variant: Int32 = try readInt(&buf)
        switch variant {


        case 1: return .Malformed(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Unsupported(
            msg: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    static func write(_ value: SlimError, into buf: inout [UInt8]) {
        switch value {


        case let .Malformed(msg):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(msg, into: &buf)
        case let .Unsupported(msg):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(msg, into: &buf)
        }
    }
}


extension SlimError: Equatable, Hashable {}

extension SlimError: Foundation.LocalizedError {
    var errorDescription: String? {
        String(reflecting: self)
    }
}

