#if swift(>=5.8)
@_documentation(visibility: private)
#endif
fileprivate struct FfiConverterSequenceTypePlanShape: FfiConverterRustBuffer {
    typealias SwiftType = [PlanShape]

    static func write(_ value: [PlanShape], into buf: inout [UInt8]) {
        let len = Int32(value.count)
        writeInt(&buf, len)
        for item in value {
            FfiConverterTypePlanShape.write(item, into: &buf)
        }
    }

    static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> [PlanShape] {
        let len: Int32 = try readInt(&buf)
        var seq = [PlanShape]()
        seq.reserveCapacity(Int(len))
        for _ in 0 ..< len {
            seq.append(try FfiConverterTypePlanShape.read(from: &buf))
        }
        return seq
    }
}

