func mergePlans(plans: [ProofPlan]) -> ProofPlan {
    return try!  FfiConverterTypeProofPlan.lift(try! rustCall() {
    uniffi_opl_ffi_fn_func_merge_plans(
        FfiConverterSequenceTypeProofPlan.lower(plans),$0
    )
})
}

func proofPlan(bundleJson: String)throws  -> ProofPlan {
    return try  FfiConverterTypeProofPlan.lift(try rustCallWithError(FfiConverterTypeSlimError.lift) {
    uniffi_opl_ffi_fn_func_proof_plan(
        FfiConverterString.lower(bundleJson),$0
    )
})
}

func verifyBundle(bundleJson: String, trustRoots: [TrustRoot], activeVersion: UInt64?) -> BundleStatus {
    return try!  FfiConverterTypeBundleStatus.lift(try! rustCall() {
    uniffi_opl_ffi_fn_func_verify_bundle(
        FfiConverterString.lower(bundleJson),
        FfiConverterSequenceTypeTrustRoot.lower(trustRoots),
        FfiConverterOptionUInt64.lower(activeVersion),$0
    )
})
}

private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private var initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 26
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_opl_ffi_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_opl_ffi_checksum_func_merge_plans() != 41554) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_opl_ffi_checksum_func_proof_plan() != 18677) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_opl_ffi_checksum_func_verify_bundle() != 39785) {
        return InitializationResult.apiChecksumMismatch
    }

    return InitializationResult.ok
}()

private func uniffiEnsureInitialized() {
    switch initializationResult {
    case .ok:
        break
    case .contractVersionMismatch:
        fatalError("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    case .apiChecksumMismatch:
        fatalError("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
}

